CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY, path TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY, title TEXT NOT NULL, content TEXT, image_url TEXT, category TEXT, published INTEGER DEFAULT 1, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY, name TEXT NOT NULL, description TEXT, price DOUBLE PRECISION, price_type TEXT DEFAULT 'flat', duration_min INTEGER, category TEXT, image_url TEXT, featured INTEGER DEFAULT 0, sort_order INTEGER DEFAULT 0, published INTEGER DEFAULT 1, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS gallery (id SERIAL PRIMARY KEY, title TEXT, bay_number TEXT, equipment TEXT, image_url TEXT, sort_order INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS appointments (id SERIAL PRIMARY KEY, customer_name TEXT NOT NULL, email TEXT, phone TEXT, vehicle TEXT, service_id INTEGER, service_name TEXT, appt_date TEXT, appt_time TEXT, notes TEXT, status TEXT DEFAULT 'pending', image_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS business_hours (id SERIAL PRIMARY KEY, day_of_week INTEGER, open_time TEXT, close_time TEXT, closed INTEGER DEFAULT 0, image_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS form_submissions (id SERIAL PRIMARY KEY, name TEXT, email TEXT, phone TEXT, message TEXT, image_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
